package net.officefloor.hq.app.holiday;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.time.LocalDate;

/** A holiday on a sheet: a day no claim falls due on when its due-by is fixed. */
@Entity
@Table(name = "holiday")
public class Holiday {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "holiday_date", nullable = false)
    private LocalDate day;

    /** The sheet's today when the holiday was added. */
    @Column(name = "added_on", nullable = false)
    private LocalDate addedOn;

    protected Holiday() {
    }

    public Holiday(String sheetId, LocalDate day, LocalDate addedOn) {
        this.sheetId = sheetId;
        this.day = day;
        this.addedOn = addedOn;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public LocalDate getDay() {
        return day;
    }

    public LocalDate getAddedOn() {
        return addedOn;
    }
}
package net.officefloor.hq.app.holiday;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.sheet.AsOfGuard;
import org.springframework.format.annotation.DateTimeFormat;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets/{sheetId}/holidays")
@Validated
public class HolidayController {

    /** A holiday as the screen shows it: its day. */
    public record HolidayView(long id, LocalDate date) {
        static HolidayView of(Holiday h) {
            return new HolidayView(h.getId(), h.getDay());
        }
    }

    /** The holiday form: the required day. */
    public record HolidayForm(@NotNull LocalDate date) {
    }

    private final HolidayService service;

    public HolidayController(HolidayService service) {
        this.service = service;
    }

    @GetMapping
    public List<HolidayView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader(value = AsOfGuard.HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE)
            LocalDate asOf) {
        return service.list(sheetId.trim()).stream()
                .filter(h -> asOf == null || !h.getAddedOn().isAfter(asOf))
                .map(HolidayView::of).toList();
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public HolidayView add(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody HolidayForm form) {
        return HolidayView.of(service.add(sheetId.trim(), user.trim(), form.date()));
    }
}
package net.officefloor.hq.app.holiday;

import java.time.LocalDate;
import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;

public interface HolidayRepository extends JpaRepository<Holiday, Long> {

    /** The holidays of a sheet, earliest day first. */
    List<Holiday> findBySheetIdOrderByDayAsc(String sheetId);

    /** Whether the day is already a holiday of the sheet. */
    boolean existsBySheetIdAndDay(String sheetId, LocalDate day);
}
package net.officefloor.hq.app.holiday;

import java.time.LocalDate;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The holidays of a sheet. */
@Service
public class HolidayService {

    private final HolidayRepository holidays;
    private final SheetService sheets;
    private final Audit audit;

    public HolidayService(HolidayRepository holidays, SheetService sheets, Audit audit) {
        this.holidays = holidays;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The holidays of the sheet, earliest day first. */
    @Transactional(readOnly = true)
    public List<Holiday> list(String sheetId) {
        return holidays.findBySheetIdOrderByDayAsc(sheetId);
    }

    /** Add a day to the sheet's holidays; refused for a day already on the list. */
    @Transactional
    public synchronized Holiday add(String sheetId, String user, LocalDate day) {
        sheets.load(sheetId, user);
        if (holidays.existsBySheetIdAndDay(sheetId, day)) {
            throw alreadyListed();
        }
        Holiday saved;
        try {
            saved = holidays.saveAndFlush(new Holiday(sheetId, day, sheets.today(sheetId)));
        } catch (DataIntegrityViolationException e) {
            throw alreadyListed();
        }
        audit.recordOnCommit("HOLIDAY_ADDED sheet=" + sheetId + " by=" + user + " date=" + day);
        return saved;
    }

    /** The terms-th business day after the day (see {@link BusinessDays#after}), skipping every
     *  Saturday, Sunday and holiday of the sheet. */
    @Transactional(readOnly = true)
    public LocalDate businessDaysAfter(String sheetId, LocalDate day, int terms) {
        Set<LocalDate> days = holidays.findBySheetIdOrderByDayAsc(sheetId).stream().map(Holiday::getDay)
                .collect(Collectors.toSet());
        return BusinessDays.after(day, terms, days);
    }

    private static ResponseStatusException alreadyListed() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "That day is already a holiday");
    }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from './session';

/** A holiday of the sheet: its day (yyyy-mm-dd). */
export interface Holiday {
  id: number;
  date: string;
}

// The holidays of the active sheet: a claim's due-by fixed at its creation is moved past them.
@Injectable({ providedIn: 'root' })
export class Holidays {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  /** The holidays of the sheet, earliest first. */
  list(sheetId: string): Promise<Holiday[]> {
    return firstValueFrom(this.http.get<Holiday[]>(this.url(sheetId)));
  }

  /** Add a day to the sheet's holidays; refused (409) for a day already on the list. */
  add(date: string): Promise<Holiday> {
    const sheetId = this.session.sheetId();
    const user = this.session.user();
    if (!sheetId || !user) throw new Error('no sheet loaded');
    return firstValueFrom(this.http.post<Holiday>(this.url(sheetId), { date }, { headers: { 'X-User': user } }));
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/holidays`;
  }
}
import { HttpErrorResponse } from '@angular/common/http';
import { Component, effect, inject, signal } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
