package net.officefloor.hq.app.claim;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Objects;

/** A revision of a claim in its sheet's history: what its figures were worked out from after a
 *  change, recorded on the sheet's today then. */
@Entity
@Table(name = "claim_revision")
public class ClaimRevision {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "claim_id", nullable = false)
    private Long claimId;

    /** The sheet's today when the revision was recorded. */
    @Column(name = "recorded_on", nullable = false)
    private LocalDate recordedOn;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "amount", nullable = false, precision = 14, scale = 2)
    private BigDecimal amount;

    @Column(name = "claim_date", nullable = false)
    private LocalDate date;

    @Enumerated(EnumType.STRING)
    @Column(name = "status", nullable = false)
    private ClaimStatus status;

    @Column(name = "settled_due", precision = 14, scale = 2)
    private BigDecimal settledDue;

    @Column(name = "stated", nullable = false)
    private boolean stated;

    @Column(name = "stated_due", precision = 14, scale = 2)
    private BigDecimal statedDue;

    @Column(name = "stated_na", nullable = false)
    private boolean statedNa;

    @Column(name = "corrected_date")
    private LocalDate correctedDate;

    @Column(name = "due_by", nullable = false)
    private LocalDate dueBy;

    @Column(name = "deferred_until")
    private LocalDate deferredUntil;

    protected ClaimRevision() {
    }

    /** A revision of the claim as it is now, recorded on the day. */
    public ClaimRevision(Claim claim, LocalDate recordedOn) {
        this.sheetId = claim.getSheetId();
        this.claimId = claim.getId();
        this.recordedOn = recordedOn;
        this.personId = claim.getPersonId();
        this.amount = claim.getAmount();
        this.date = claim.getDate();
        this.status = claim.getStatus();
-- The sheet's history keeps its periods too: a revision of each period a change left different from
-- its last revision, stamped with the sheet's today then. Each person's fixed due-total is kept as
-- text: "person-id:total", separated by ";".
CREATE TABLE period_revision (
    id            BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id      VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    period_id     BIGINT         NOT NULL,
    recorded_on   DATE           NOT NULL,
    name          VARCHAR(100)   NOT NULL,
    from_date     DATE           NOT NULL,
    to_date       DATE           NOT NULL,
    closed        BOOLEAN        NOT NULL,
    soft_closed   BOOLEAN        NOT NULL,
    closed_total  DECIMAL(14, 2),
    person_totals VARCHAR(4000)  NOT NULL
);
CREATE INDEX period_revision_sheet ON period_revision (sheet_id, id);

INSERT INTO period_revision (sheet_id, period_id, recorded_on, name, from_date, to_date, closed, soft_closed,
        closed_total, person_totals)
    SELECT p.sheet_id, p.id, s.today, p.name, p.from_date, p.to_date, p.closed, p.soft_closed, p.closed_total,
        COALESCE((SELECT LISTAGG(CAST(t.person_id AS VARCHAR) || ':' || CAST(t.total AS VARCHAR), ';')
            WITHIN GROUP (ORDER BY t.person_id) FROM period_person_total t WHERE t.period_id = p.id), '')
    FROM period p JOIN sheet s ON s.id = p.sheet_id ORDER BY p.id;

-- The sheet's today when a patron was named; null for one named before it was kept (named all along).
ALTER TABLE patron ADD COLUMN named_on DATE;
        return change(sheetId, user, claimIds, ClaimStatus.OPEN);
    }

    /** Settle each of the claims that can be settled, in list order, exactly as settling one: a claim
     *  a clerk's limit leaves pending counts as settled; each that cannot is refused and left as it
     *  is, and so is an id that names no claim on the sheet. */
    public Outcome settle(String sheetId, String user, Set<Long> claimIds) {
        return change(sheetId, user, claimIds, ClaimStatus.SETTLED);
    }

    private Outcome change(String sheetId, String user, Set<Long> claimIds, ClaimStatus to) {
        if (sheets.archived(sheetId)) {
            return new Outcome(0, claimIds.size());
        }
        int done = 0;
        for (Claim claim : inListOrder(sheetId, claimIds)) {
            try {
                claims.changeStatus(sheetId, user, claim.getId(), to);
                done++;
            } catch (ResponseStatusException refused) {
                // left as it is
            }
        }
        return new Outcome(done, claimIds.size() - done);
    }

    /** The claims of the ids on the sheet in list order: people in the order they were added, newest
     *  claim first within a person. */
    private List<Claim> inListOrder(String sheetId, Set<Long> claimIds) {
        Map<Long, Integer> rank = new HashMap<>();
        List<Person> listed = people.findBySheetIdOrderByIdAsc(sheetId);
        for (int i = 0; i < listed.size(); i++) {
            rank.put(listed.get(i).getId(), i);
        }
        return repository.findBySheetIdOrderByListedDesc(sheetId).stream()
                .filter(c -> claimIds.contains(c.getId()))
                .sorted(Comparator.comparingInt((Claim c) -> rank.getOrDefault(c.getPersonId(), Integer.MAX_VALUE))
                        .thenComparing(Claim::getListed, Comparator.reverseOrder()))
                .toList();
    }
}

